import {api,session,login,register,signout,authSettings,googleLogin,callback,recover,changePassword,safeNext} from './auth.js';
import {icon,googleMark} from './icons.js';
const $=s=>document.querySelector(s);
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'TSh '+Number(n||0).toLocaleString('en-US');
const date=s=>s?new Date(s).toLocaleDateString('sw-TZ',{day:'numeric',month:'short',year:'numeric'}):'—';
const labels={draft:'Rasimu',submitted:'Inakaguliwa',changes_requested:'Inahitaji marekebisho',published:'Imechapishwa',rejected:'Imekataliwa',archived:'Imehifadhiwa',paid:'Imelipwa',pending:'Inasubiri',failed:'Imeshindikana',expired:'Muda umeisha',active:'Hai',restricted:'Imesitishwa',declined:'Imekataliwa',open:'Linashughulikiwa',resolved:'Limejibiwa',reader:'Msomaji',author:'Mwandishi',admin:'Admin',accepted:'Imepokelewa',unknown:'Haijathibitishwa',submitting:'Inatumwa'};
const badge=s=>`<span class="badge ${h(s)}">${h(labels[s]||s)}</span>`;
const link=(url,label,cls='btn secondary',ico='')=>`<a href="${h(url)}" class="${cls}">${ico?icon(ico,17):''}${label}</a>`;
const btn=(action,label,id='',cls='btn secondary small',ico='')=>`<button type="button" class="${cls}" data-action="${action}" data-id="${h(id)}">${ico?icon(ico,16):''}${label}</button>`;
const cover=(b,cls='',lazy=true)=>b.cover_url?`<img src="${h(b.cover_url)}" alt="Jalada: ${h(b.title)}" class="${cls}" ${lazy?'loading="lazy"':'fetchpriority="high"'} decoding="async">`:`<span class="cover-empty">${icon('book',35)}<br>Jalada halijawekwa</span>`;
const empty=(title,text,action='',ico='book')=>`<div class="empty"><div class="empty-icon">${icon(ico,25)}</div><h3>${h(title)}</h3><p>${h(text)}</p>${action}</div>`;
const heading=(title,sub,action='')=>`<div class="page-heading"><div><h1>${h(title)}</h1><p>${h(sub)}</p></div>${action}</div>`;
const stat=(label,value,ico='chart',note='')=>`<div class="stat-card"><div class="stat-head">${h(label)}${icon(ico,17)}</div><strong>${h(value)}</strong>${note?`<small>${h(note)}</small>`:''}</div>`;
const field=(name,label,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${h(value)}" ${extra}></label>`;
const textarea=(name,label,value='',extra='')=>`<label class="field">${label}<textarea name="${name}" ${extra}>${h(value)}</textarea></label>`;
const table=(heads,body,no='Hakuna rekodi kwa sasa.',cls='')=>`<div class="table-wrap ${h(cls)}"><table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${heads.length}" class="muted">${no}</td></tr>`}</tbody></table></div>`;
const row=cells=>`<tr>${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`;
const bookCell=b=>`<div class="book-cell">${cover(b)}<div><span class="cell-title">${h(b.title)}</span><span class="cell-sub">${h(b.author_name||'')} · PDF</span></div></div>`;
let catalog=null,me=null,adminData=null,authorData=null,libraryData=null,paymentTimer=null,toastTimer=null,routeSequence=0;
let filterCategory='',filterSearch='',googleEnabled=false;
function toast(text,error=false){const t=$('#toast');t.textContent=text;t.className='toast'+(error?' error':'');t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,6000);}
function modal(title,content){$('#modal-title').textContent=title;$('#modal-content').innerHTML=content;$('#modal').showModal();}
$('#modal-close').onclick=()=>$('#modal').close();
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
async function getCatalog(){if(!catalog)catalog=await api('catalog');return catalog;}
async function getMe(){if(!me&&session())me=(await api('market-me')).user;return me;}
async function getAdmin(){if(!adminData)adminData=await api('market-admin-data');return adminData;}
async function getAuthor(){if(!authorData)authorData=await api('market-author-data');return authorData;}
async function getLibrary(){if(!libraryData)libraryData=await api('market-library');return libraryData;}
function invalidate(){adminData=null;authorData=null;libraryData=null;catalog=null;}
const brand=()=>`<a href="/" class="brand" aria-label="AKILI STORE, mwanzo"><span class="wordmark">AKILI<span>STORE</span></span></a>`;
function header(){
 const p=location.pathname;
 const nav=`<a href="/books" class="${p==='/books'?'active':''}">Vitabu</a><a href="/categories" class="${p==='/categories'?'active':''}">Makundi</a><a href="/help">Msaada</a>`;
 return `<header class="container topbar">${brand()}<nav class="main-nav" aria-label="Menyu kuu">${nav}</nav><div class="header-actions">${me?link(me.role==='admin'?'/admin':'/my-library',me.role==='admin'?'Dashboard':'Maktaba yangu','btn secondary','library'):link('/login','Ingia','btn ghost')}${!me?link('/register','Jisajili','btn'):''}<button class="icon-button mobile-toggle" type="button" data-action="menu" aria-label="Fungua menyu" aria-expanded="false">${icon('menu',20)}</button></div><nav id="mobile-nav" class="mobile-nav" aria-label="Menyu ya simu" hidden>${nav}${link(me?'/profile-settings':'/login',me?'Akaunti yangu':'Ingia kwenye akaunti','btn ghost')}${me?.role==='author'?link('/author-dashboard','Dashboard ya mwandishi','btn ghost'):''}</nav></header>`;
}
const footer=()=>`<footer class="footer"><div class="container footer-inner"><span>© ${new Date().getFullYear()} AKILI STORE · Powered By TIDA TZ COMPANY</span><div class="footer-links"><a href="/platform-policies">Masharti na faragha</a><a href="/help">Mawasiliano</a></div></div></footer>`;
function publicPage(content){return header()+`<main id="main" tabindex="-1">${content}</main>`+footer();}
function card(b){return `<article class="book-card"><a href="/book/${encodeURIComponent(b.slug)}"><div class="cover-box">${cover(b)}<span class="format-tag">eBOOK · PDF</span></div><p class="category">${h(b.category)}</p><h3>${h(b.title)}</h3></a><p class="author">${h(b.author_name)}</p><div class="book-bottom"><span>${money(b.price_tzs)}</span><a href="/book/${encodeURIComponent(b.slug)}" class="arrow-link" aria-label="Fungua ${h(b.title)}">${icon('arrow',15)}</a></div></article>`;}
function home(c){
 const b=c.books[0];
 return publicPage(`<div class="container storefront"><section class="storefront-find" aria-label="Tafuta vitabu"><h1>Tafuta kitabu.</h1><form class="storefront-search" id="search-form" role="search">${icon('search',21)}<input name="q" aria-label="Tafuta kitabu au mwandishi" placeholder="Jina la kitabu au mwandishi" autocomplete="off"><button class="btn" type="submit">Tafuta</button></form></section>${b?`<article class="featured-product"><a class="featured-cover" href="/book/${encodeURIComponent(b.slug)}" aria-label="Fungua ${h(b.title)}">${cover(b,'',false)}</a><div class="featured-info"><p class="product-kind">${h(b.category)} · PDF</p><h2><a href="/book/${encodeURIComponent(b.slug)}">${h(b.title)}</a></h2><p class="product-author">${h(b.author_name)}</p><p class="product-price">${money(b.price_tzs)}</p></div><div class="button-row featured-actions">${link('/checkout/'+b.id,'Nunua kitabu','btn primary')}${b.has_preview?btn('preview','Soma sampuli',b.id,'btn secondary'):''}</div></article>`:empty('Hakuna vitabu kwa sasa','Vitabu vilivyochapishwa vitaonekana hapa.')}${c.books.length>1?`<section class="more-books"><div class="section-head"><h2>Vitabu vingine</h2>${link('/books','Vitabu vyote','text-link','arrow')}</div><div class="books-grid">${c.books.slice(1,5).map(card).join('')}</div></section>`:''}</div>`);
}
function catalogView(c){const q=new URLSearchParams(location.search);filterSearch=q.get('q')||'';filterCategory=q.get('category')||'';return publicPage(`<div class="container section"><div class="section-head"><div><p class="eyebrow">MAKTABA YA MAARIFA</p><h1>${location.pathname==='/categories'?'Soma kwa kundi lako.':'Tafuta cha kusoma.'}</h1><p>Tafuta kitabu, mada au mwandishi unayempenda.</p></div></div><div class="toolbar"><label class="search-field">${icon('search',17)}<input id="catalog-search" aria-label="Tafuta kwenye vitabu" placeholder="Tafuta kitabu au mwandishi…" value="${h(filterSearch)}"></label><select class="filter-select" id="sort-books" aria-label="Panga vitabu"><option value="new">Vilivyoangaziwa</option><option value="low">Bei: ndogo hadi kubwa</option><option value="high">Bei: kubwa hadi ndogo</option><option value="az">Majina A–Z</option></select></div><div class="chips">${['',...new Set(c.books.map(b=>b.category).filter(Boolean))].map(x=>`<button class="chip ${x===filterCategory?'active':''}" type="button" data-action="category" data-id="${h(x)}">${h(x||'Vitabu vyote')}</button>`).join('')}</div><p class="muted small" id="result-count" aria-live="polite"></p><div class="books-grid" id="catalog-grid"></div></div>`);}
function updateCatalog(){if(!$('#catalog-grid'))return;let books=catalog.books.filter(b=>(!filterCategory||b.category===filterCategory)&&[b.title,b.author_name,b.description,b.category].some(x=>String(x||'').toLowerCase().includes(filterSearch.toLowerCase())));const sort=$('#sort-books')?.value;if(sort==='low')books.sort((a,b)=>a.price_tzs-b.price_tzs);if(sort==='high')books.sort((a,b)=>b.price_tzs-a.price_tzs);if(sort==='az')books.sort((a,b)=>a.title.localeCompare(b.title));$('#catalog-grid').innerHTML=books.map(card).join('')||`<div style="grid-column:1/-1">${empty('Hakuna kitabu kilichopatikana','Jaribu maneno mengine au chagua vitabu vyote.',btn('clear-filters','Ondoa vichujio'))}</div>`;$('#result-count').textContent=`${books.length} ${books.length===1?'kitabu kimepatikana':'vitabu vimepatikana'}`;}
function detail(b,c,reviews=[]){return publicPage(`<div class="container"><div class="crumb"><a href="/books">Vitabu</a>${icon('chevron',12)}<span>${h(b.category)}</span></div><article class="detail"><div class="detail-cover">${cover(b,'',false)}</div><div><span class="eyebrow">${h(b.category)} · eBOOK</span><h1>${h(b.title)}</h1>${b.subtitle?`<p class="muted">${h(b.subtitle)}</p>`:''}<div class="author-line"><span class="avatar">${icon('user',18)}</span><span>Na <strong>${h(b.author_name)}</strong></span></div><div class="book-meta"><span>${icon('book',15)} PDF</span><span>${h(b.language)}</span>${b.page_count?`<span>Kurasa ${b.page_count}</span>`:''}</div><p class="detail-price">${money(b.price_tzs)}</p><div class="button-row">${link('/checkout/'+b.id,'Nunua sasa','btn primary','arrow')}${b.has_preview?btn('preview','Soma sampuli',b.id,'btn secondary','book'):''}</div><p class="hero-note">${icon('shield',15)} Baada ya malipo, kitabu kinaongezwa kwenye maktaba yako.</p><div class="tabs"><a href="#about" class="active">Kuhusu kitabu</a><a href="#reviews">Maoni (${reviews.length})</a></div><div class="detail-copy" id="about"><h2>Ndani ya kitabu hiki</h2><p class="description">${h(b.description||c.settings.about_book||b.subtitle||'Maelezo ya kitabu yataongezwa na mwandishi.')}</p>${c.settings.contents&&b.slug==='mifumo-7-muhimu'?`<h3>Yaliyomo</h3><p class="description">${h(c.settings.contents)}</p>`:''}</div><section id="reviews"><h2 style="font-size:20px">Maoni ya wasomaji</h2>${reviews.length?reviews.map(r=>`<div class="ticket"><span style="color:#bd8739">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span><p>${h(r.body)}</p><span class="muted small">Mnunuzi aliyethibitishwa · ${date(r.created_at)}</span></div>`).join(''):`<p class="muted small">Bado hakuna maoni. Wasomaji walionunua kitabu wanaweza kutoa maoni kupitia maktaba yao.</p>`}</section></div></article></div>`);}
function authView(mode='login'){
 const reg=mode==='register',forgot=mode==='forgot',reset=mode==='reset',q=new URLSearchParams(location.search),next=q.get('next');
 const password=!forgot?`<div class="field"><label for="auth-password">${reset?'Nenosiri jipya':'Nenosiri'}</label><div class="password-entry"><input id="auth-password" name="password" type="password" required minlength="${reg||reset?12:1}" autocomplete="${reg||reset?'new-password':'current-password'}"><button type="button" data-action="toggle-password" aria-controls="auth-password" aria-pressed="false">Onyesha</button></div>${reg||reset?'<small>Angalau herufi 12.</small>':''}</div>`:'';
 return publicPage(`<div class="auth-layout compact-auth"><div class="auth-content"><div class="auth-card"><h1>${reg?'Fungua akaunti.':forgot?'Umesahau nenosiri?':reset?'Nenosiri jipya.':'Ingia kwenye akaunti.'}</h1><p>${forgot?'Tutakutumia kiungo kwenye email yako.':reset?'Hifadhi nenosiri lako jipya.':reg?'Nunua vitabu na uvisome kwenye maktaba yako.':'Endelea kwenye maktaba yako.'}</p>${!forgot&&!reset&&googleEnabled?`<button class="btn secondary block google-button" data-action="google" type="button">${googleMark()} Endelea kwa Google</button><div class="divider">au tumia email</div>`:''}<form id="auth-form" class="form-stack" data-mode="${mode}">${reg?field('name','Jina lako','','text','required autocomplete="name" minlength="2" maxlength="100"'):''}${!reset?field('email','Email yako','','email','required autocomplete="email" maxlength="160"'):''}${password}${!reg&&!forgot&&!reset?'<a class="password-link" href="/forgot-password">Umesahau nenosiri?</a>':''}<div id="form-error" class="error-box" role="alert" hidden></div><button type="submit" class="btn block">${reg?'Fungua akaunti':forgot?'Tuma kiungo':reset?'Hifadhi nenosiri':'Ingia'} ${icon('arrow',17)}</button></form>${!forgot&&!reset?`<p class="auth-foot">${reg?'Tayari una akaunti?':'Huna akaunti?'} <a class="text-link" href="/${reg?'login':'register'}${next?'?next='+encodeURIComponent(next):''}">${reg?'Ingia':'Jisajili'}</a></p>`:link('/login','Rudi kuingia','text-link')}<p class="auth-foot"><a href="/platform-policies">Masharti na faragha</a></p></div></div></div>`);
}
function dashboard(content,title,area='reader'){
 const isAdmin=area==='admin',isAuthor=area==='author';
 const nav=isAdmin?[['/admin','grid','Muhtasari'],['/admin/books','book','Vitabu na ukaguzi'],['/admin/users','users','Watumiaji na waandishi'],['/admin/orders','receipt','Mauzo na malipo'],['/admin/withdrawals','wallet','Mapato na utoaji'],['/admin/messages','mail','Ujumbe wa SMS'],['/admin/support','help','Msaada'],['/admin/settings','settings','Mipangilio']]:isAuthor?[['/author-dashboard','grid','Muhtasari'],['/author/books','book','Vitabu vyangu'],['/sales-analytics','chart','Mauzo yangu'],['/withdrawal-request','wallet','Pochi na utoaji'],['/my-library','library','Maktaba yangu'],['/profile-settings','settings','Mipangilio']]:[['/reader-dashboard','grid','Muhtasari'],['/my-library','library','Maktaba yangu'],['/order-history','receipt','Manunuzi yangu'],['/notifications','bell','Arifa'],['/help','help','Msaada'],['/profile-settings','settings','Mipangilio']];
 const current=location.pathname;
 return `<div class="dashboard"><button class="mobile-side-cover" data-action="side-close" aria-label="Funga menyu"></button><aside class="sidebar" id="sidebar"><div class="side-brand">${brand()}</div><p class="workspace-label">${isAdmin?'USIMAMIZI WA DUKA':isAuthor?'ENEO LA MWANDISHI':'AKAUNTI YANGU'}</p><nav class="side-nav" aria-label="Menyu ya dashboard">${nav.map(([url,i,label])=>`<a href="${url}" class="${current===url||(url==='/admin/books'&&current.startsWith('/admin/books/'))||(url==='/author/books'&&current.startsWith('/author/books/'))?'active':''}">${icon(i,18)}${label}</a>`).join('')}</nav>${me.role==='admin'&&!isAdmin?`<div class="workspace-label">USIMAMIZI</div><nav class="side-nav"><a href="/admin">${icon('shield',18)}Admin dashboard</a></nav>`:''}${me.role==='author'&&!isAuthor?`<div class="workspace-label">MWANDISHI</div><nav class="side-nav"><a href="/author-dashboard">${icon('edit',18)}Dashboard ya mwandishi</a></nav>`:''}<div class="sidebar-bottom"><nav class="side-nav"><a href="/books">${icon('search',18)}Tafuta vitabu</a><a href="#" data-action="logout">${icon('logout',18)}Toka</a></nav><div class="side-user"><span class="avatar">${h(me.display_name.slice(0,2).toUpperCase())}</span><div><span>${h(me.display_name)}</span><small>${labels[me.role]||me.role}</small></div></div></div></aside><div class="dash-body"><header class="dash-top"><div class="dash-breadcrumb"><button type="button" class="icon-button mobile-toggle" data-action="side-open" aria-label="Fungua menyu" aria-expanded="false">${icon('menu',20)}</button><span>AKILI STORE</span>${icon('chevron',12)}<span>${h(title)}</span></div><div class="dash-top-right">${link('/books','Fungua duka','btn ghost small','arrow')}<a href="/notifications" class="icon-button" aria-label="Arifa">${icon('bell',19)}</a><a href="/profile-settings" class="avatar" aria-label="Mipangilio ya akaunti">${h(me.display_name.slice(0,2).toUpperCase())}</a></div></header><main id="main" class="dash-main" tabindex="-1">${!isAdmin&&!isAuthor&&me.author_invitation?`<section class="panel invitation-panel"><h2>Umealikwa kuwa mwandishi</h2><p class="muted small">Mwaliko umetumwa kwa ${h(me.email)}.</p>${btn('accept-email-invite','Kubali mwaliko',me.author_invitation,'btn primary','check')}</section>`:''}${content}</main></div></div>`;
}
function libraryCards(books){return `<div class="books-grid">${books.map(b=>`<article class="library-card"><div class="cover-box">${cover(b)}</div><h3>${h(b.title)}</h3><p>${h(b.author_name)}</p><div class="progress-bar"><span style="width:${b.progress?Math.round(b.progress.page/b.progress.total_pages*100):0}%"></span></div><p style="margin-top:8px">${b.progress?'Ukurasa '+b.progress.page+' / '+b.progress.total_pages:'Tayari kuanza kusoma'}</p>${link('/reader.html?book='+b.id,b.progress?'Endelea kusoma':'Anza kusoma','btn block','book')}<div class="button-row" style="margin-top:8px">${btn('review','Toa maoni',b.id,'btn ghost small','star')}</div></article>`).join('')}</div>`;}
function readerHome(lib,orders){const reading=lib.books.filter(b=>b.progress&&b.progress.page<b.progress.total_pages),done=lib.books.filter(b=>b.progress&&b.progress.page>=b.progress.total_pages);return dashboard(heading('Karibu, '+me.display_name.split(' ')[0]+'.','Maarifa yako. Kwa mwendo wako.',link('/books','Tafuta vitabu','btn secondary small','search'))+`<div class="stat-grid">${stat('Vitabu kwenye maktaba',lib.books.length,'library')}${stat('Unaendelea kusoma',reading.length,'book')}${stat('Umemaliza kusoma',done.length,'check')}</div><section class="panel"><div class="panel-head"><h2>Endelea na safari yako</h2>${link('/my-library','Maktaba yote','text-link','arrow')}</div>${lib.books.length?libraryCards(lib.books.slice(0,3)):empty('Maktaba yako inaanzia hapa','Vitabu utakavyonunua vitaonekana hapa. Chagua kitabu chako cha kwanza.',link('/books','Tafuta vitabu','btn','arrow'),'library')}</section>`,'Muhtasari');}
function ordersTable(orders,admin=false){
 const books=new Map((admin?adminData.books:catalog.books).map(b=>[b.id,b])),heads=admin?['Mnunuzi / Tarehe','Kitabu','Kiasi','Hali','Hatua']:['Kitabu','Tarehe','Kiasi','Hali','Hatua'];
 const body=orders.map(o=>{const b=books.get(o.book_id),amount=money(o.amount_tzs)+(o.verification_test?'<span class="cell-sub">Jaribio la mfumo</span>':''),action=admin?(o.status==='pending'?btn('verify-payment','Kagua malipo',o.id):o.status==='paid'?btn('resend-access','Tuma access',o.id):'—'):(o.status==='pending'?btn('check-order','Kagua malipo',o.id):o.status==='paid'?link('/reader.html?book='+o.book_id,'Soma kitabu','btn secondary small','book'):link('/checkout/'+o.book_id+(o.verification_test&&me.role==='admin'?'?verify=1':''),'Jaribu tena','btn secondary small'));
 const cells=admin?[`<span class="cell-title">${h(o.customer_name)}</span><span class="cell-sub">${h(o.customer_email)}<br>${date(o.created_at)}</span>`,h(b?.title||'Kitabu'),amount,badge(o.status),action]:[h(b?.title||'Kitabu'),date(o.created_at),amount,badge(o.status),action];
 return `<tr>${cells.map((value,i)=>`<td data-label="${h(heads[i])}">${value}</td>`).join('')}</tr>`;}).join('');
 return table(heads,body,'Bado hakuna manunuzi.','orders-table');
}
function adminHome(d){const paid=d.orders.filter(o=>o.status==='paid');const pending=d.books.filter(b=>b.status==='submitted');const sold=paid.reduce((s,o)=>s+o.amount_tzs,0);return dashboard(heading('Muhtasari wa duka','Kila kinachohitaji umakini wako, mahali pamoja.',link('/admin/books/new','Ongeza kitabu','btn primary','plus'))+(!d.integration.payments_enabled?`<div class="notice">${icon('shield',18)}<span>Malipo bado hayajawashwa. Kamilisha jaribio la Snippe kwenye Mauzo na malipo kabla ya kupokea mauzo mapya.</span></div>`:'')+`<div class="stat-grid">${stat('Mauzo yaliyothibitishwa',money(sold),'wallet','Kutoka kwenye oda '+d.orders.length+' za karibuni')}${stat('Vitabu vilivyochapishwa',d.books.filter(b=>b.status==='published').length,'book')}${stat('Vinavyosubiri ukaguzi',pending.length,'clock')}</div><div class="two-col"><section class="panel"><div class="panel-head"><h2>Vinavyohitaji umakini</h2>${link('/admin/books','Angalia vyote','text-link','arrow')}</div>${pending.length?pending.slice(0,5).map(b=>`<div class="mini-book">${cover(b)}<div class="mini-book-info"><h3>${h(b.title)}</h3><p>${h(b.author_name)}</p></div>${link('/admin/books/'+b.id+'/edit','Kagua','btn secondary small')}</div>`).join(''):empty('Ukaguzi uko sawa','Hakuna kitabu kipya kinachosubiri kukaguliwa.','','check')}</section><section class="panel"><div class="panel-head"><h2>Maandalizi ya duka</h2></div>${[[d.books.some(b=>b.cover_path&&b.pdf_path),'Jalada na PDF halisi'],[d.books.some(b=>b.preview_path),'Sampuli ya kitabu'],[true,'Akaunti ya admin'],[googleEnabled,'Kuingia kwa Google'],[d.integration.payments_enabled,'Malipo ya Snippe']].map(([done,label])=>`<div class="onboarding-row"><span class="onboarding-icon ${done?'done':''}">${icon(done?'check':'clock',14)}</span><span>${label}</span></div>`).join('')}</section></div><section class="panel"><div class="panel-head"><h2>Mauzo ya karibuni</h2>${link('/admin/orders','Historia ya mauzo','text-link','arrow')}</div>${ordersTable(d.orders.slice(0,5),true)}</section>`,'Muhtasari','admin');}
function booksManage(d,admin=false){const base=admin?'/admin/books':'/author/books',books=d.books;return dashboard(heading(admin?'Vitabu na ukaguzi':'Vitabu vyangu',admin?'Dhibiti maudhui yanayoonekana dukani.':'Andaa, wasilisha na fuatilia vitabu vyako.',link(base+'/new','Ongeza kitabu','btn primary','plus'))+`<section class="panel"><div class="toolbar"><label class="search-field">${icon('search',17)}<input id="manage-search" placeholder="Tafuta kitabu…" aria-label="Tafuta kitabu kwenye dashboard"></label><span class="muted small">${books.length} ${books.length===1?'kitabu':'vitabu'}</span></div>${table(['Kitabu','Bei','Hali','Kimesasishwa','Hatua'],books.map(b=>`<tr data-filter="${h((b.title+' '+b.author_name+' '+b.status).toLowerCase())}">${[bookCell(b),money(b.price_tzs),badge(b.status),date(b.updated_at),link(base+'/'+b.id+'/edit',admin?'Kagua / Hariri':'Hariri','btn secondary small','edit')].map(x=>`<td>${x}</td>`).join('')}</tr>`).join(''),'Bado hakuna vitabu. Bonyeza Ongeza kitabu kuanza.')}</section>${admin?`<section class="panel"><div class="panel-head"><h2>Maoni ya wasomaji</h2><span class="muted small">${d.reviews.filter(r=>r.status==='pending').length} yanasubiri</span></div>${d.reviews.length?d.reviews.map(r=>`<div class="ticket"><h3>${h(d.books.find(b=>b.id===r.book_id)?.title||'Kitabu')} · ${r.rating}/5</h3><p>${h(r.body)}</p><div class="button-row">${badge(r.status)}${r.status==='pending'?btn('approve-review','Idhinisha',r.id)+btn('reject-review','Kataa',r.id):''}</div></div>`).join(''):empty('Hakuna maoni kwa sasa','Maoni ya wanunuzi yataonekana hapa kwa ukaguzi.','','star')}</section>`:''}` ,admin?'Vitabu na ukaguzi':'Vitabu vyangu',admin?'admin':'author');}
function editor(b={},admin=false){const isNew=!b.id,base=admin?'/admin/books':'/author/books';return dashboard(heading(isNew?'Ongeza kitabu':'Hariri kitabu',isNew?'Anza na taarifa muhimu, kisha pakia mafaili.':b.title,link(base,'Rudi kwenye vitabu','btn secondary small'))+`<form id="book-form" data-id="${h(b.id||'')}" class="editor-layout"><div><section class="panel"><div class="editor-section"><span class="step-number">01</span><h2>Taarifa za kitabu</h2></div><div class="form-grid"><div class="wide">${field('title','Jina la kitabu',b.title||'','text','required maxlength="200" placeholder="Mfano: Mifumo 7 Muhimu Kila Biashara Inayohitaji"')}</div><div class="wide">${field('subtitle','Kichwa kidogo (si lazima)',b.subtitle||'','text','maxlength="300"')}</div>${field('slug','Kiungo cha kitabu',b.slug||'','text','required pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="100" placeholder="mfumo-wa-biashara"')}${field('author_name','Jina la mwandishi',b.author_name||me.display_name,'text','required maxlength="200"')}${field('category','Kundi',b.category||'Biashara','text','required list="categories" maxlength="80"')}${field('language','Lugha',b.language||'Kiswahili','text','required maxlength="60"')}${field('price_tzs','Bei (TSh)',b.price_tzs||25000,'number','required min="500" step="1"')}${field('page_count','Idadi ya kurasa',b.page_count||'','number','min="1" max="20000"')}<div class="wide">${textarea('description','Kitabu kinamsaidiaje msomaji?',b.description||'','maxlength="10000" placeholder="Eleza maarifa, mada na manufaa halisi anayopata msomaji…"')}</div></div><datalist id="categories">${['Biashara','Fedha','Teknolojia','Maendeleo binafsi','Uongozi','Mauzo na masoko','Elimu','Imani'].map(c=>`<option value="${c}">`).join('')}</datalist></section><section class="panel"><div class="editor-section"><span class="step-number">02</span><h2>Jalada, kitabu na sampuli</h2></div>${isNew?`<div class="notice info">${icon('upload',18)}Hifadhi rasimu kwanza, kisha pakia mafaili.</div>`:''}<div class="form-stack">${[['cover','Jalada la kitabu','Picha PNG, JPG au WebP · hadi MB 10','image/png,image/jpeg,image/webp','cover_path'],['pdf','PDF kamili','Faili binafsi · hadi MB 50','application/pdf','pdf_path'],['preview','Sampuli ya kurasa 2–4','PDF tofauti na kitabu kamili · hadi MB 10','application/pdf','preview_path']].map(([kind,title,note,accept,key])=>`<label class="file-upload"><strong>${title}</strong><span class="muted small">${note}</span><input type="file" data-upload="${kind}" accept="${accept}" ${isNew?'disabled':''} aria-label="${title}"><input type="hidden" name="${key}" value="${h(b[key]||'')}"><span class="file-state" id="file-state-${kind}">${b[key]?'Faili limepakiwa':''}</span></label>`).join('')}</div></section><div id="form-error" class="error-box" role="alert" hidden></div><div class="button-row"><button class="btn" type="submit">${icon('check',17)} Hifadhi rasimu</button>${!isNew&&['draft','changes_requested','rejected'].includes(b.status)?btn('submit-book','Wasilisha kwa ukaguzi',b.id,'btn secondary','arrow'):''}</div></div><aside class="editor-aside"><section class="panel"><p class="eyebrow">MWONEKANO DUKANI</p><div class="cover-box">${cover(b)}</div><h3>${h(b.title||'Jina la kitabu')}</h3><p class="muted small">${h(b.author_name||me.display_name)}</p><strong>${money(b.price_tzs||25000)}</strong><p style="margin:15px 0 0">${badge(b.status||'draft')}</p>${b.moderation_note?`<div class="notice info">${h(b.moderation_note)}</div>`:''}</section>${!isNew?`<section class="panel"><h2>Kagua mafaili</h2><div class="form-stack">${b.pdf_path?btn('inspect-pdf','Fungua PDF kamili',b.id,'btn secondary small','book'):''}${b.preview_path?btn('inspect-preview','Fungua sampuli',b.id,'btn secondary small','book'):''}</div></section>`:''}${admin&&!isNew?`<section class="panel"><h2>Uamuzi wa admin</h2><p class="muted small">Hakikisha taarifa, jalada, PDF na sampuli ziko tayari.</p><div class="form-stack">${btn('publish-book','Idhinisha na chapisha',b.id,'btn primary','check')}${btn('changes-book','Omba marekebisho',b.id)}${btn('reject-book','Kataa',b.id)}${b.status==='published'?btn('archive-book','Ondoa dukani',b.id):''}</div></section>`:''}</aside></form>` ,isNew?'Kitabu kipya':'Hariri kitabu',admin?'admin':'author');}
function usersView(d){return dashboard(heading('Watumiaji na waandishi','Waandishi wanaingia kwa mwaliko. Wasomaji wanajisajili moja kwa moja.',btn('invite-author','Alika mwandishi','','btn primary','mail'))+`<section class="panel"><div class="toolbar"><label class="search-field">${icon('search',17)}<input id="manage-search" placeholder="Tafuta jina…" aria-label="Tafuta mtumiaji"></label><span class="muted small">${d.profiles.length} akaunti</span></div>${table(['Mtumiaji','Jukumu','Alijiunga','Hali','Hatua'],d.profiles.map(p=>`<tr data-filter="${h((p.display_name+' '+p.email+' '+p.role).toLowerCase())}">${[`<span class="cell-title">${h(p.display_name)}</span><span class="cell-sub">${h(p.email||'')}</span><span class="cell-sub">${h(p.phone||'')}</span>`,p.user_id===me.id?'Admin':labels[p.role],date(p.created_at),badge(p.status),p.user_id!==me.id?btn(p.status==='active'?'restrict-user':'activate-user',p.status==='active'?'Sitisha':'Rejesha',p.user_id):'Akaunti yako'].map(x=>`<td>${x}</td>`).join('')}</tr>`).join(''))}</section><section class="panel"><h2>Mialiko ya waandishi</h2>${table(['Email','Imetumwa','Inaisha','Hali'],(d.invitations||[]).map(i=>row([h(i.email),i.email_sent_at?date(i.email_sent_at):'Kiungo cha kushirikisha',date(i.expires_at),i.accepted_at?'Imekubaliwa':Date.parse(i.expires_at)<Date.now()?'Imeisha':'Inasubiri'])).join(''),'Hakuna mialiko kwa sasa.')}</section><div class="notice info">${icon('shield',18)}Mwaliko wa mwandishi unaisha baada ya siku saba na unakubaliwa kwa email ile iliyoalikwa. Hauruhusu mtu kujipa admin.</div>`,'Watumiaji na waandishi','admin');}
function financeView(d,admin=false){const withdrawals=d.withdrawals;const earned=admin?d.ledger.filter(x=>x.account==='author').reduce((s,x)=>s+x.amount_tzs,0):d.balance.earned;return dashboard(heading(admin?'Mapato na utoaji':'Pochi yangu',admin?'Fuatilia mapato na maombi yaliyohifadhiwa kwenye mfumo.':'Mapato kutoka kwenye mauzo yaliyothibitishwa.',!admin?btn('withdraw-modal','Omba kutoa pesa','','btn primary','wallet'):'')+`<div class="stat-grid">${stat(admin?'Mapato ya waandishi':'Mapato yote',money(earned),'wallet')}${stat(admin?'Maombi yanayosubiri':'Salio linalopatikana',admin?withdrawals.filter(w=>w.status==='pending').length:money(d.balance.available),'clock')}${stat('Yaliyotolewa',money(admin?withdrawals.filter(w=>w.status==='paid').reduce((s,w)=>s+w.amount_tzs-w.fee_tzs,0):d.balance.withdrawn),'check')}</div>${!admin?`<div class="notice info">${icon('wallet',18)}Kiwango cha chini: ${money(d.policy.withdrawal_min_tzs)}. Ada kwa ombi: ${money(d.policy.withdrawal_fee_tzs)}. Kiasi unachoomba kinajumuisha ada.</div>`:''}<section class="panel"><div class="panel-head"><h2>Historia ya maombi</h2></div>${table(admin?['Mwandishi','Kiasi / Ada','Namba','Tarehe','Hali','Hatua']:['Kiasi','Ada','Utapokea','Tarehe','Hali'],withdrawals.map(w=>row(admin?[h(d.profiles.find(p=>p.user_id===w.user_id)?.display_name||'Mwandishi'),`${money(w.amount_tzs)}<span class="cell-sub">Ada: ${money(w.fee_tzs)}</span>`,h(w.phone),date(w.created_at),badge(w.status),w.status==='pending'?`<div class="row-actions">${btn('pay-withdrawal','Rekodi malipo',w.id)}${btn('decline-withdrawal','Kataa',w.id)}</div>`:h(w.reference||w.note||'—')]:[money(w.amount_tzs),money(w.fee_tzs),money(w.amount_tzs-w.fee_tzs),date(w.created_at),badge(w.status)])).join(''),'Hakuna ombi la kutoa pesa kwa sasa.')}</section>${admin?`<section class="panel"><h2>Mgao wa mauzo yaliyorekodiwa</h2><p class="muted small">Mgao unahifadhiwa baada ya malipo kuthibitishwa. Hizi ni jumla kutoka rekodi ${d.ledger.length} za karibuni.</p>${table(['Akaunti','Jumla'],['author','platform','system'].map(a=>row([a==='author'?'Waandishi':a==='platform'?'AKILI STORE':'Uendeshaji wa mfumo',money(d.ledger.filter(x=>x.account===a).reduce((s,x)=>s+x.amount_tzs,0))])).join(''))}</section>`:''}` ,admin?'Mapato na utoaji':'Pochi na utoaji',admin?'admin':'author');}
function authorHome(d){return dashboard(heading('Karibu, mwandishi.','Maarifa yako yanaweza kumsaidia mtu kuchukua hatua.',link('/author/books/new','Ongeza kitabu','btn primary','plus'))+`<div class="stat-grid">${stat('Vitabu vyangu',d.books.length,'book')}${stat('Mauzo yaliyothibitishwa',d.ledger.length,'receipt')}${stat('Salio linalopatikana',money(d.balance.available),'wallet')}</div><section class="panel"><div class="panel-head"><h2>Vitabu vyako</h2>${link('/author/books','Angalia vyote','text-link','arrow')}</div>${d.books.length?d.books.slice(0,5).map(b=>`<div class="mini-book">${cover(b)}<div class="mini-book-info"><h3>${h(b.title)}</h3><p>${money(b.price_tzs)}</p></div>${badge(b.status)}${link('/author/books/'+b.id+'/edit','Hariri','btn secondary small')}</div>`).join(''):empty('Andika. Wasilisha. Fikia wasomaji.','Anza kwa kuongeza kitabu chako cha kwanza. Admin atakagua kabla ya kuchapishwa.',link('/author/books/new','Ongeza kitabu','btn','plus'))}</section>`,'Muhtasari','author');}
function settingsView(d){const s=d.settings;return dashboard(heading('Mipangilio ya duka','Muonekano na mawasiliano.')+`<div class="two-col"><section class="panel"><h2>Muonekano na mawasiliano</h2><form id="site-form" class="form-stack">${field('primary_color','Rangi ya vitufe',s.primary_color,'color','required')}${field('support_email','Email ya msaada',s.support_email,'email','required')}${field('contact','Simu / mawasiliano',s.contact,'text','maxlength="500"')}${textarea('about_author','Kuhusu mwandishi wa kitabu cha mwanzo',s.about_author,'maxlength="10000"')}${textarea('contents','Yaliyomo — kitabu cha mwanzo',s.contents,'maxlength="10000"')}<div id="form-error" class="error-box" role="alert" hidden></div><button class="btn" type="submit">Hifadhi mabadiliko</button></form></section><section class="panel"><h2>Akaunti yangu</h2><p class="muted small">${h(me.email)}</p>${link('/profile-settings','Mipangilio ya akaunti','btn secondary','settings')}</section></div><section class="panel"><h2>Historia ya usimamizi</h2>${table(['Tarehe','Shughuli','Rekodi'],d.audits.slice(0,30).map(a=>row([date(a.created_at),h(a.action),h(a.target_id?.slice(0,12)||'—')])).join(''))}</section>`,'Mipangilio','admin');}
function smsConnectionView(d){
 if(d.environment_managed)return '';
 const attrs='autocomplete="off" autocapitalize="none" spellcheck="false" minlength="8" maxlength="4096" required';
 return `<section class="panel"><details ${d.configured?'':'open'}><summary><strong>${d.configured?'Muunganisho wa eHub':'Unganisha eHub'}</strong></summary><p class="small muted">Sender: AKILI STORE. Funguo huhifadhiwa kwa usalama na hazionyeshwi tena baada ya kuhifadhi.</p>
 <details ${d.api_configured?'':'open'}><summary>1. ${d.api_configured?'API imeunganishwa · badilisha funguo':'Weka funguo za API'}</summary>
 <form id="sms-connect-form" class="form-stack" autocomplete="off"><p class="small muted">Nakili funguo kutoka eHub → Developer → API keys. Kuhakiki muunganisho hakutumi SMS wala kukata salio.</p>${field('apiKey','API key','','password',attrs)}${field('apiSecret','API secret','','password',attrs)}<div id="form-error" class="error-box" role="alert" hidden></div><button type="submit" class="btn">Hifadhi na hakiki</button></form></details>
 ${d.api_configured?`<details ${d.webhook_configured?'':'open'}><summary>2. ${d.webhook_configured?'Webhook imehifadhiwa · badilisha ufunguo':'Unganisha taarifa za kufika kwa SMS'}</summary><p class="small muted">Kwenye eHub → Developer → Webhook, weka anwani hii, washa webhook kisha nakili signing secret hapa.</p>${field('webhookUrl','Webhook URL',location.origin+'/api?action=sms-webhook','url','readonly autocomplete="off"')}<form id="sms-webhook-form" class="form-stack" autocomplete="off">${field('webhookSecret','Webhook signing secret','','password',attrs)}<div id="form-error" class="error-box" role="alert" hidden></div><button type="submit" class="btn">Hifadhi webhook</button></form></details>`:''}</details></section>`;
}
function smsView(d){return dashboard(heading('Ujumbe wa SMS','Tuma ujumbe na ufuatilie kufika kwake.',btn('sms-balance','Angalia salio','','btn secondary','receipt'))+`${smsConnectionView(d)}<p id="sms-balance" role="status" class="muted small"></p><section class="panel"><form id="sms-form" class="form-stack">${field('name','Jina la ujumbe','','text','maxlength="120" placeholder="Mfano: Taarifa kwa waandishi"')}${textarea('recipients','Namba za wapokeaji','','required placeholder="07XXXXXXXX, 07YYYYYYYY" maxlength="16000"')}<p class="small muted">Namba 1 hadi 1,000. Tenganisha kwa koma au mstari mpya. Namba inayojirudia itatumwa mara moja.</p>${textarea('message','Ujumbe','','required maxlength="640" placeholder="Andika ujumbe wako hapa"')}<div id="form-error" class="error-box" role="alert" hidden></div><button type="submit" class="btn" ${d.configured?'':'disabled'}>Hakiki ujumbe</button></form></section><section class="panel"><h2>Historia ya ujumbe</h2>${table(['Ujumbe','Wapokeaji','Hali','Zimefika','Zimeshindwa','Gharama'],d.campaigns.map(c=>row([`<strong>${h(c.name||'Ujumbe wa SMS')}</strong><span class="cell-sub">${date(c.created_at)}</span><span class="cell-sub">${h(c.message.slice(0,100))}</span>`,c.recipient_count,badge(c.status)+(c.status==='unknown'?'<span class="cell-sub">Hakiki eHub kabla ya kutuma tena.</span>':''),c.delivered,c.failed,c.total_cost===null?'—':money(c.total_cost)])).join(''))}</section>`,'Ujumbe wa SMS','admin');}
function profileView(){return dashboard(heading('Mipangilio ya akaunti','Jina lako, mawasiliano na usalama wa kuingia.')+`<div class="two-col"><section class="panel"><h2>Taarifa zangu</h2><form id="profile-form" class="form-stack">${field('display_name','Jina lako',me.display_name,'text','required minlength="2" maxlength="100"')}${field('email','Email',me.email,'email','disabled')}${field('phone','Namba ya simu',me.phone||'','tel','maxlength="25"')}${textarea('bio','Kuhusu wewe',me.bio||'','maxlength="1500"')}<div id="form-error" class="error-box" role="alert" hidden></div><button class="btn" type="submit">Hifadhi taarifa</button></form></section><section class="panel"><h2>Nenosiri na usalama</h2><p class="muted small">Tutakutumia kiungo cha kubadili nenosiri kwenye email yako.</p>${btn('reset-password','Tuma kiungo cha kubadili nenosiri','','btn secondary','mail')}<hr style="border:0;border-top:1px solid var(--line);margin:26px 0"><p class="muted small">Jukumu: ${labels[me.role]}</p>${btn('logout','Toka kwenye akaunti','','btn secondary','logout')}</section></div>`,'Mipangilio');}
function supportView(tickets=[],admin=false){const content=heading(admin?'Msaada kwa watumiaji':'Tunaweza kusaidia.','Fuatilia ombi na majibu yake hapa.')+`<div class="${admin?'':'two-col'}">${!admin?`<section class="panel"><h2>Tuma ombi la msaada</h2><form id="support-form" class="form-stack">${field('subject','Kichwa cha ombi','','text','required minlength="3" maxlength="160" placeholder="Mfano: Nahitaji msaada kufungua kitabu"')}${textarea('message','Eleza unachohitaji','','required minlength="10" maxlength="4000"')}<div id="form-error" class="error-box" role="alert" hidden></div><button class="btn" type="submit">Tuma ombi ${icon('arrow',17)}</button></form></section>`:''}<section class="panel"><h2>${admin?'Maombi ya msaada':'Maombi yangu'}</h2>${tickets.length?tickets.map(t=>`<article class="ticket"><div class="section-head" style="margin-bottom:10px"><h3>${h(t.subject)}</h3>${badge(t.status)}</div><p>${h(t.message)}</p>${t.reply?`<div class="reply"><strong>Jibu la msaada</strong><br>${h(t.reply)}</div>`:''}<p class="muted small" style="margin-top:12px">${date(t.created_at)}</p>${admin&&t.status==='open'?btn('reply-ticket','Jibu ombi',t.id,'btn secondary small','mail'):''}</article>`).join(''):empty('Hakuna maombi kwa sasa',admin?'Maombi mapya yataonekana hapa.':'Ukituma ombi, utaona maendeleo na jibu lake hapa.','','help')}</section></div>`;return me?dashboard(content,admin?'Msaada':'Msaada',admin?'admin':'reader'):publicPage(`<div class="container section">${heading('Tunaweza kusaidia.','Wasiliana na timu ya AKILI STORE.')}<div class="two-col"><section class="panel"><h2>Unahitaji msaada?</h2><p class="muted small">Ingia kwenye akaunti kutuma ombi na kufuatilia majibu.</p>${link('/login?next=/help','Ingia kupata msaada','btn','arrow')}</section><section class="panel"><h2>Mawasiliano</h2><p class="muted small">${h(catalog?.settings.support_email||'tidatzsupport@gmail.com')}</p><p class="muted small">${h(catalog?.settings.contact||'')}</p><p class="small">TIDA TZ COMPANY · Dar es Salaam, Tanzania</p></section></div></div>`);}
function verificationCheckout(bookId){
 if(me?.role!=='admin')return false;
 let pending;try{pending=JSON.parse(sessionStorage.getItem('akili-checkout')||'null');}catch{}
 if(pending?.orderId&&pending.bookId===bookId&&(!pending.userId||pending.userId===me.id))return pending.verification===true;
 return !catalog.payments_enabled&&new URLSearchParams(location.search).get('verify')==='1';
}
function verificationAccountView(){
 return publicPage(`<section class="container section"><div class="auth-card" style="margin:0 auto"><p class="eyebrow">JARIBIO · TSh 500</p><h1>Tumia akaunti ya admin.</h1><p>Umeingia kwa <strong>${h(me.email)}</strong>. Jaribio hili linapatikana kwa akaunti yenye ruhusa ya admin.</p>${btn('switch-account','Ingia kwa akaunti ya admin',location.pathname+location.search,'btn primary block')}<p class="auth-foot">${link('/reader-dashboard','Rudi kwenye akaunti yangu','text-link')}</p></div></section>`);
}
function paymentActions(d){
 const b=d.books.find(b=>b.status==='published');
 return `<div class="button-row">${btn('verify-snippe','Thibitisha muunganisho','','btn secondary','shield')}${b&&!d.integration.payments_enabled&&!d.orders.some(o=>o.verification_test&&o.status==='paid')?link('/checkout/'+b.id+'?verify=1','Jaribu malipo · TSh 500','btn'):''}</div>`;
}
function checkoutView(b){
 const verification=verificationCheckout(b.id),amount=verification?500:b.price_tzs,available=catalog.payments_enabled||verification;
 return publicPage(`<div class="container"><div class="crumb"><a href="${verification?'/admin/orders':'/book/'+encodeURIComponent(b.slug)}">${verification?'Rudi kwenye malipo':'Rudi kwenye kitabu'}</a>${icon('chevron',12)}<span>Malipo</span></div><div class="checkout"><section><p class="eyebrow">${verification?'ADMIN · JARIBIO LA MFUMO':'HATUA YA MWISHO'}</p><h1>${verification?'Jaribio la malipo.':'Lipa kwa simu.'}</h1><p class="muted small">${verification?'Haya ni malipo halisi ya TSh 500 ya kuhakiki Snippe na upatikanaji wa kitabu. Bei ya duka inabaki '+money(b.price_tzs)+'.':'Weka namba ya pesa za simu. Kitabu kitaingia kwenye maktaba yako baada ya malipo.'}</p>${!available?'<div class="notice">Malipo hayapatikani kwa sasa. Tafadhali rudi tena baadaye au wasiliana na msaada.</div>':''}<ol class="checkout-steps" aria-label="Hatua za ununuzi"><li aria-current="step">Taarifa</li><li>Malipo</li><li>Kitabu</li></ol><form id="checkout-form" class="form-stack" data-id="${b.id}" data-verification="${verification}">${field('name','Jina kamili',me.display_name,'text','required minlength="2" maxlength="120" autocomplete="name"')}${field('email','Email ya akaunti',me.email,'email','disabled')}${field('phone','Namba ya simu',me.phone||'','tel','required inputmode="tel" pattern="(0[67][0-9]{8}|255[67][0-9]{8}|\\+255[67][0-9]{8})" placeholder="07XXXXXXXX"')}<p class="muted small">Ombi la malipo litatumwa kwenye simu yako. Tumia PIN yako kwenye simu pekee.</p><div id="form-error" class="error-box" role="alert" hidden></div><button type="submit" class="btn primary block" ${available?'':'disabled'}>Lipa ${money(amount)} ${icon('arrow',17)}</button></form><div id="payment-stage" class="payment-stage" hidden><p class="payment-detail" id="payment-detail"></p><div class="notice info">${icon('clock',20)}<span id="payment-message" role="status">Tunasubiri uthibitisho wa malipo…</span></div><div class="button-row">${btn('check-payment','Kagua malipo','','btn secondary')}${link('/order-history','Manunuzi yangu','btn ghost small')}</div></div></section><aside class="checkout-summary"><p class="eyebrow">${verification?'JARIBIO · MALIPO HALISI':'UNACHONUNUA'}</p><div class="mini-book">${cover(b)}<div class="mini-book-info"><h3>${h(b.title)}</h3><p>${h(b.author_name)} · PDF</p></div></div><div class="summary-row"><span>${verification?'Jaribio la mfumo':'Kitabu'}</span><span>${money(amount)}</span></div><div class="summary-row total"><span>Jumla</span><span>${money(amount)}</span></div><p class="hero-note">${icon('shield',16)} Access baada ya malipo kuthibitishwa.</p></aside></div></div>`);
}
function policies(){return publicPage(`<article class="container legal"><p class="eyebrow">AKILI STORE · TIDA TZ COMPANY</p><h1>Masharti na faragha</h1><h2>Ununuzi na upatikanaji wa vitabu</h2><p>AKILI STORE inauza vitabu vya kidijitali. Bei ya kila kitabu huonyeshwa kwa Shilingi za Tanzania (TSh). Baada ya malipo kuthibitishwa na mfumo, kitabu kinaongezwa kwenye akaunti ya mnunuzi. Malipo yanayosubiri au yaliyoshindikana hayafungui kitabu.</p><h2>Matumizi ya maudhui</h2><p>Ununuzi unakupa ruhusa ya kutumia kitabu binafsi. Hauhamishi hakimiliki. Usisambaze, kuuza tena au kuchapisha maudhui bila ruhusa ya mwenye haki. Waandishi wanawajibika kuwa na haki za maudhui wanayowasilisha.</p><h2>Malipo yenye tatizo</h2><p>Ukilipia bila kupata kitabu, ukatozwa mara mbili au ukashindwa kufungua faili, wasiliana na msaada ukiweka taarifa ya oda na uthibitisho wa muamala. Timu itahakiki rekodi na kushughulikia tatizo au ombi la kurejeshewa fedha kulingana na hali ya muamala na haki zinazotumika.</p><h2>Taarifa tunazotumia</h2><p>Tunahifadhi taarifa za akaunti, manunuzi, malipo, maendeleo ya usomaji na maombi ya msaada kwa ajili ya kukupa huduma na kulinda akaunti. Huduma za uthibitishaji wa akaunti, kuhifadhi faili na malipo hushughulikia taarifa zinazohitajika kwa kazi hizo. PIN ya pesa za simu haikusanywi na AKILI STORE.</p><h2>Akaunti na maombi ya faragha</h2><p>Linda nenosiri na viungo vyako binafsi vya kitabu. Unaweza kuomba msaada kuhusu taarifa zako, kusahihisha taarifa au kuomba kufunga akaunti kupitia timu ya msaada. Baadhi ya rekodi za miamala zinaweza kuhitajika kubaki kwa ajili ya uhasibu, utatuzi wa migogoro na wajibu wa kisheria.</p><h2>Mawasiliano na hakimiliki</h2><p>Kwa msaada, maswali kuhusu faragha au taarifa ya maudhui yanayokiuka haki, tumia ${h(catalog?.settings.support_email||'tidatzsupport@gmail.com')}. Mfumo unaendeshwa na TIDA TZ COMPANY, Dar es Salaam, Tanzania.</p>${link('/help','Wasiliana na msaada','btn secondary','help')}</article>`);}
async function render(){
 const sequence=++routeSequence;clearInterval(paymentTimer);paymentTimer=null;$('#modal').close();
 const path=location.pathname.replace(/\/$/,'')||'/';
 document.title='AKILI STORE';
 try{
  if(path==='/auth/callback'){
   const result=await callback();me=null;if(result.recovery){$('#app').innerHTML=authView('reset');return;}if(!session()){toast('Email imethibitishwa. Ingia kwenye akaunti yako.');return navigate('/login',true);}await getMe();return navigate(result.next||(me.role==='admin'?'/admin':'/reader-dashboard'),true);
  }
  await getCatalog();if(session())await getMe();
  if(sequence!==routeSequence)return;
  const privateRoute=/^\/(admin|author|my-library|reader-dashboard|order-history|profile-settings|notifications|sales-analytics|withdrawal-request|checkout|invite)/.test(path);
  if(privateRoute&&!me)return navigate('/login?next='+encodeURIComponent(location.pathname+location.search),true);
  const isAdmin=path==='/admin'||path.startsWith('/admin/'),isAuthor=path.startsWith('/author')||['/sales-analytics','/withdrawal-request'].includes(path);
  if(isAdmin&&me.role!=='admin')throw Error('Eneo hili linahitaji ruhusa ya admin.');
  if(isAuthor&&!['author','admin'].includes(me.role))throw Error('Eneo la mwandishi linafunguliwa baada ya mwaliko kukubaliwa.');
  let content;
  if(path==='/')content=home(catalog);
  else if(['/books','/search','/categories'].includes(path))content=catalogView(catalog);
  else if(path.startsWith('/book/')){const slug=decodeURIComponent(path.slice(6)),book=catalog.books.find(b=>b.slug===slug);if(!book)throw Error('Kitabu hiki hakipatikani kwa sasa.');const r=await api('book-reviews',{bookId:book.id}).catch(()=>({reviews:[]}));content=detail(book,catalog,r.reviews);document.title='AKILI STORE';}
  else if(['/login','/register','/forgot-password'].includes(path)){if(me&&path!=='/forgot-password')return navigate(safeNext(new URLSearchParams(location.search).get('next')|| (me.role==='admin'?'/admin':'/reader-dashboard')),true);content=authView(path==='/register'?'register':path==='/forgot-password'?'forgot':'login');}
  else if(path==='/reader-dashboard'){const [lib,orders]=await Promise.all([getLibrary(),api('market-orders')]);content=readerHome(lib,orders.orders);}
  else if(path==='/my-library'){const lib=await getLibrary();content=dashboard(heading('Maktaba yangu','Vitabu vyako, tayari kusoma popote.',link('/books','Tafuta vitabu','btn secondary small','search'))+(lib.books.length?libraryCards(lib.books):empty('Maktaba yako bado iko tupu','Chagua kitabu, lipia na kitaonekana hapa pamoja na maendeleo yako ya kusoma.',link('/books','Chagua kitabu','btn','arrow'),'library')),'Maktaba yangu');}
  else if(path==='/order-history'){const d=await api('market-orders');content=dashboard(heading('Manunuzi yangu','Historia ya oda na hali ya malipo.')+`<section class="panel">${ordersTable(d.orders)}</section>`,'Manunuzi yangu');}
  else if(path==='/notifications'){const d=await api('market-notifications');content=dashboard(heading('Arifa','Taarifa kuhusu akaunti, vitabu na maombi yako.',d.notifications.some(n=>!n.read_at)?btn('read-notifications','Weka zote zimesomwa'):'')+`<section class="panel">${d.notifications.length?d.notifications.map(n=>`<a href="${h(safeNext(n.href))}" class="notification-item"><span class="avatar">${icon('bell',18)}</span><div><h3>${h(n.title)}${!n.read_at?' · Mpya':''}</h3><p>${h(n.body)}</p><time>${date(n.created_at)}</time></div></a>`).join(''):empty('Hakuna arifa mpya','Arifa zako zitaonekana hapa.','','bell')}</section>`,'Arifa');}
  else if(path==='/profile-settings')content=profileView();
  else if(path==='/help'){const d=me?await api('market-support'):{tickets:[]};content=supportView(d.tickets);}
  else if(path==='/platform-policies')content=policies();
  else if(path.startsWith('/checkout/')){const book=catalog.books.find(b=>b.id===path.split('/')[2]);if(!book)throw Error('Kitabu hakijapatikana.');if(new URLSearchParams(location.search).get('verify')==='1'&&me.role!=='admin')content=verificationAccountView();else{const lib=await getLibrary();if(lib.books.some(b=>b.id===book.id))return navigate('/my-library',true);content=checkoutView(book);}}
  else if(path==='/invite'){const token=new URLSearchParams(location.search).get('token')||'';content=dashboard(heading('Mwaliko wa mwandishi','Karibu kuchapisha maarifa yako kwenye AKILI STORE.')+`<section class="panel"><h2>Kubali mwaliko</h2><p class="muted small">Akaunti yako: ${h(me.email)}. Mwaliko utakubaliwa ikiwa email hii ndiyo iliyoalikwa na muda haujaisha.</p>${btn('accept-invite','Kubali na fungua eneo la mwandishi',token,'btn primary','check')}</section>`,'Mwaliko');}
  else if(isAdmin){const d=await getAdmin();if(path==='/admin')content=adminHome(d);else if(path==='/admin/books')content=booksManage(d,true);else if(path.startsWith('/admin/books/')){const id=path.split('/')[3],b=id==='new'?{}:d.books.find(b=>b.id===id);if(!b)throw Error('Kitabu hakijapatikana.');content=editor(b,true);}else if(['/admin/users','/admin/authors'].includes(path))content=usersView(d);else if(['/admin/orders','/admin/payments'].includes(path))content=dashboard(heading('Mauzo na malipo','Manunuzi na uthibitisho wa malipo.',paymentActions(d))+`<section class="panel">${ordersTable(d.orders,true)}</section>`,'Mauzo na malipo','admin');else if(['/admin/withdrawals','/admin/reports'].includes(path))content=financeView(d,true);else if(path==='/admin/support')content=supportView(d.tickets,true);else if(path==='/admin/settings')content=settingsView(d);else if(path==='/admin/messages')content=smsView(await api('market-admin-sms-data'));else if(path==='/admin/reviews')content=booksManage(d,true);}
  else if(isAuthor){const d=await getAuthor();if(path==='/author-dashboard')content=authorHome(d);else if(path==='/author/books')content=booksManage(d);else if(path.startsWith('/author/books/')){const id=path.split('/')[3],b=id==='new'?{}:d.books.find(b=>b.id===id);if(!b)throw Error('Kitabu hakijapatikana.');content=editor(b);}else if(path==='/withdrawal-request')content=financeView(d);else if(path==='/sales-analytics')content=dashboard(heading('Mauzo yangu','Mapato yanatokana na malipo yaliyothibitishwa.')+`<div class="stat-grid">${stat('Vitabu vilivyouzwa',d.ledger.length,'receipt')}${stat('Mapato yangu',money(d.balance.earned),'wallet')}${stat('Salio linalopatikana',money(d.balance.available),'chart')}</div><section class="panel">${table(['Tarehe','Oda','Mapato yako'],d.ledger.map(l=>row([date(l.created_at),h(l.order_id.slice(0,12)),money(l.amount_tzs)])).join(''),'Bado hakuna mauzo.')}</section>`,'Mauzo yangu','author');}
  if(!content)content=publicPage(`<div class="container section">${empty('Ukurasa haujapatikana','Tumia menyu kufungua sehemu unayohitaji.',link('/','Rudi mwanzo','btn','arrow'))}</div>`);
  if(sequence!==routeSequence)return;$('#app').innerHTML=content;
  if(catalog.settings.primary_color)document.documentElement.style.setProperty('--accent',catalog.settings.primary_color);
  updateCatalog();
  if(path.startsWith('/checkout/'))resumePayment(path.split('/')[2]);
 }catch(e){
  if(sequence!==routeSequence)return;
  if(e.status===401){await signout();me=null;return navigate('/login?next='+encodeURIComponent(location.pathname),true);}
  $('#app').innerHTML=publicPage(`<div class="container section">${empty('Hatukuweza kufungua sehemu hii',e.message,btn('retry','Jaribu tena','','btn','arrow'),'help')}</div>`);
 }
}
function navigate(path,replace=false){path=safeNext(path);if(replace)history.replaceState({},'',path);else history.pushState({},'',path);window.scrollTo(0,0);return render();}
window.addEventListener('popstate',render);
let busy=false,smsAttempt=null;
async function mutation(action,values,message){if(busy)return;busy=true;try{await api(action,values);invalidate();$('#modal').close();await render();toast(message);}catch(e){toast(e.message,true);}finally{busy=false;}}
function modalForm(title,fields,action,values={},label='Hifadhi'){
 modal(title,`<form id="modal-form" class="form-stack" data-api="${action}" data-values="${h(JSON.stringify(values))}">${fields}<p class="modal-error" id="modal-error" role="alert" hidden></p><button class="btn" type="submit">${label}</button></form>`);
}
document.addEventListener('click',async e=>{
 const el=e.target.closest('[data-action]');
 if(el){e.preventDefault();const a=el.dataset.action,id=el.dataset.id;try{
  if(a==='menu'){const nav=$('#mobile-nav');nav.hidden=!nav.hidden;el.setAttribute('aria-expanded',String(!nav.hidden));return;}
  if(a==='side-open'||a==='side-close'){$('#sidebar')?.classList.toggle('open',a==='side-open');$('.mobile-side-cover')?.classList.toggle('open',a==='side-open');document.querySelector('[data-action="side-open"]')?.setAttribute('aria-expanded',String(a==='side-open'));return;}
  if(a==='category'){filterCategory=id;document.querySelectorAll('.chip').forEach(c=>c.classList.toggle('active',c.dataset.id===id));updateCatalog();return;}
  if(a==='clear-filters'){filterSearch='';filterCategory='';$('#catalog-search').value='';document.querySelectorAll('.chip').forEach(c=>c.classList.toggle('active',c.dataset.id===''));updateCatalog();return;}
  if(a==='logout'){await signout();me=null;invalidate();return navigate('/login');}
  if(a==='toggle-password'){const input=$('#auth-password'),show=input.type==='password';input.type=show?'text':'password';el.textContent=show?'Ficha':'Onyesha';el.setAttribute('aria-pressed',String(show));return;}
  if(a==='check-order'){el.disabled=true;const r=await api('status',{orderId:id});invalidate();await render();toast(r.status==='paid'?'Malipo yamethibitishwa. Fungua kitabu chako.':r.status==='pending'?'Malipo bado yanasubiri uthibitisho.':'Hali ya malipo: '+(labels[r.status]||r.status));return;}
  if(a==='switch-account'){const next=safeNext(id);await signout();me=null;invalidate();return navigate('/login?next='+encodeURIComponent(next),true);}
  if(a==='google')return googleLogin(new URLSearchParams(location.search).get('next')||'');
  if(a==='retry'){catalog=null;return render();}
  if(a==='preview'){el.disabled=true;const data=await api('preview',{bookId:id});modal('Sampuli ya kitabu',`<p class="muted small">${h(data.title)}</p><p class="small">Sampuli hii ni sehemu ya kitabu. PDF kamili inafunguliwa baada ya ununuzi.</p><a class="btn block" href="${h(data.url)}" target="_blank" rel="noopener noreferrer">${icon('book',17)} Fungua sampuli ya PDF</a>`);return;}
  if(a==='inspect-pdf'||a==='inspect-preview'){el.disabled=true;const data=await api('market-inspect-file',{bookId:id,kind:a==='inspect-pdf'?'pdf':'preview'});modal('Kagua faili',`<p class="muted small">Kiungo cha muda cha ukaguzi wa faili.</p><a href="${h(data.url)}" target="_blank" rel="noopener noreferrer" class="btn block">Fungua PDF ${icon('arrow',17)}</a>`);return;}
  if(a==='review'){modalForm('Maoni yako kuhusu kitabu',`<label class="field">Alama<select name="rating" required><option value="5">5 — Bora sana</option><option value="4">4 — Kizuri</option><option value="3">3 — Wastani</option><option value="2">2 — Kinahitaji maboresho</option><option value="1">1 — Hakikukidhi</option></select></label>${textarea('body','Umejifunza nini?','','required minlength="10" maxlength="2000"')}<p class="muted small">Maoni yatakaguliwa kabla ya kuonekana dukani.</p>`,'market-review',{bookId:id},'Tuma maoni');return;}
  if(a==='invite-author'){modalForm('Alika mwandishi',field('email','Email ya mwandishi','','email','required')+'<p class="muted small">Mwaliko utatumwa kwa email ikiwa huduma ya email imeunganishwa. Utapata pia kiungo cha kushirikisha. Unaisha baada ya siku saba.</p>','market-admin-invite',{},'Tuma mwaliko');return;}
  if(a==='submit-book'){modalForm('Wasilisha kitabu kwa ukaguzi','<p class="muted small">Jalada, PDF kamili na sampuli vitakaguliwa. Hifadhi mabadiliko yako kabla ya kuwasilisha.</p>','market-submit-book',{id},'Wasilisha sasa');return;}
  if(['publish-book','changes-book','reject-book','archive-book'].includes(a)){
   const status={'publish-book':'published','changes-book':'changes_requested','reject-book':'rejected','archive-book':'archived'}[a];
   modalForm(a==='publish-book'?'Idhinisha na chapisha kitabu':a==='archive-book'?'Ondoa kitabu dukani':'Uamuzi wa ukaguzi',`<p class="muted small">${a==='publish-book'?'Kitabu kitaonekana kwa wasomaji baada ya taarifa na mafaili kuhakikiwa.':a==='archive-book'?'Kitabu hakitaonekana dukani. Waliokinunua wataendelea kukifikia.':'Mwandishi ataona sababu hii kwenye dashboard yake.'}</p>${textarea('note','Maelezo ya uamuzi','','maxlength="2000" '+(['changes_requested','rejected'].includes(status)?'required minlength="5"':''))}`,'market-admin-moderate',{id,status},a==='publish-book'?'Chapisha':'Hifadhi uamuzi');return;
  }
  if(['restrict-user','activate-user'].includes(a)){modalForm(a==='restrict-user'?'Sitisha akaunti':'Rejesha akaunti','<p class="muted small">Mabadiliko haya yatarekodiwa kwenye historia ya usimamizi.</p>','market-admin-user',{userId:id,status:a==='restrict-user'?'restricted':'active'},'Thibitisha');return;}
  if(a==='approve-review'||a==='reject-review')return mutation('market-admin-review',{id,status:a==='approve-review'?'published':'rejected'},'Uamuzi umehifadhiwa.');
  if(a==='read-notifications')return mutation('market-notifications-read',{},'Arifa zimewekwa zimesomwa.');
  if(a==='accept-email-invite'){await api('market-accept-email-invite',{id});me=null;await getMe();invalidate();toast('Karibu kwenye eneo la mwandishi.');return navigate('/author-dashboard');}
  if(a==='accept-invite'){await api('market-accept-invite',{token:id});me=null;await getMe();invalidate();toast('Karibu kwenye eneo la mwandishi.');return navigate('/author-dashboard');}
  if(a==='reply-ticket'){modalForm('Jibu ombi la msaada',textarea('reply','Jibu la msaada','','required minlength="3" maxlength="4000"'),'market-admin-support',{id},'Tuma jibu');return;}
  if(a==='withdraw-modal'){const d=await getAuthor();modalForm('Omba kutoa pesa',`<p class="muted small">Salio: ${money(d.balance.available)}. Ada ${money(d.policy.withdrawal_fee_tzs)} itakatwa kwenye kiasi unachoomba.</p>${field('amount_tzs','Kiasi (TSh)','','number',`required min="${d.policy.withdrawal_min_tzs}" max="${d.balance.available}" step="1"`)}${field('phone','Namba ya kupokea pesa',me.phone||'','tel','required placeholder="07XXXXXXXX"')}`,'market-withdraw',{},'Wasilisha ombi');return;}
  if(a==='pay-withdrawal'||a==='decline-withdrawal'){modalForm(a==='pay-withdrawal'?'Rekodi malipo yaliyofanyika':'Kataa ombi la kutoa pesa',a==='pay-withdrawal'?`<p class="notice info">Rekodi hii haitumi pesa. Weka reference baada ya kumlipa mwandishi kupitia njia iliyokubaliwa.</p>${field('reference','Reference ya malipo','','text','required minlength="5" maxlength="160"')}`:textarea('note','Sababu ya kukataa','','required minlength="5" maxlength="1000"'),'market-admin-withdrawal',{id,status:a==='pay-withdrawal'?'paid':'declined'},'Hifadhi');return;}
  if(a==='verify-payment'){el.disabled=true;const r=await api('admin-verify',{orderId:id});invalidate();await render();toast('Hali ya malipo: '+(labels[r.status]||r.status));return;}
  if(a==='resend-access'){el.disabled=true;await api('admin-resend',{orderId:id});toast('Kiungo cha access kimetumwa kwenye email ya mnunuzi.');return;}
  if(a==='reset-password'){el.disabled=true;await recover(me.email);toast('Angalia email yako kwa kiungo cha kubadili nenosiri.');return;}
  if(a==='verify-snippe'){el.disabled=true;const r=await api('admin-snippe-health');modal('Snippe',`<p>Muunganisho wa akaunti umethibitishwa.</p><p class="muted small">${r.payments_enabled?'Kupokea malipo kumewashwa.':'Kamilisha jaribio la ununuzi kabla ya kuwasha malipo.'}</p>`);return;}
  if(a==='sms-balance'){el.disabled=true;const r=await api('market-admin-sms-account');$('#sms-balance').textContent='Sender: '+r.sender+' · Salio: '+r.balance+' SMS';return;}
  if(a==='check-payment')return checkPayment();
 }catch(ex){toast(ex.message,true);}finally{if(el.isConnected)el.disabled=false;}return;}
 const anchor=e.target.closest('a');if(!anchor||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||anchor.target==='_blank'||anchor.hasAttribute('download'))return;
 const url=new URL(anchor.href,location.href);if(url.origin!==location.origin||url.pathname.endsWith('.html')||url.hash&&url.pathname===location.pathname||url.pathname==='/reader.html')return;
 e.preventDefault();await navigate(url.pathname+url.search+url.hash);
});
document.addEventListener('input',e=>{if(e.target.id==='catalog-search'){filterSearch=e.target.value;updateCatalog();}if(e.target.id==='manage-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('tr[data-filter]').forEach(row=>row.hidden=!row.dataset.filter.includes(q));}});
document.addEventListener('change',async e=>{
 if(e.target.id==='sort-books')updateCatalog();const kind=e.target.dataset.upload;if(!kind)return;
 const file=e.target.files[0],form=$('#book-form'),id=form?.dataset.id;if(!file||!id)return;
 e.target.disabled=true;const status=$('#file-state-'+kind);status.textContent='Inapakia…';
 try{
  if(kind!=='cover'){const signature=new TextDecoder().decode(new Uint8Array(await file.slice(0,5).arrayBuffer()));if(signature!=='%PDF-')throw Error('Chagua faili halisi la PDF.');}
  const signed=await api('market-upload',{bookId:id,kind,mime:file.type,size:file.size});const r=await fetch(signed.url,{method:'PUT',headers:{'Content-Type':file.type},body:file});if(!r.ok)throw Error('Faili halijapakiwa. Jaribu tena.');
  form.elements.namedItem(kind==='cover'?'cover_path':kind==='pdf'?'pdf_path':'preview_path').value=signed.path;
  const values=Object.fromEntries(new FormData(form));values.id=id;await api('market-save-book',values);invalidate();status.textContent='Faili limepakiwa na kuhifadhiwa.';toast('Faili limehifadhiwa.');
 }catch(ex){status.textContent=ex.message;toast(ex.message,true);}finally{e.target.disabled=false;}
});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!['search-form','auth-form','book-form','modal-form','site-form','profile-form','support-form','checkout-form','sms-form','sms-connect-form','sms-webhook-form'].includes(form.id))return;e.preventDefault();
 const values=Object.fromEntries(new FormData(form)),button=form.querySelector('button[type="submit"]');if(button)button.disabled=true;
 const err=form.querySelector('#form-error,#modal-error');if(err)err.hidden=true;
 try{
  if(form.id==='sms-connect-form'||form.id==='sms-webhook-form'){
   const connecting=form.id==='sms-connect-form',result=await api(connecting?'market-admin-sms-connect':'market-admin-sms-webhook',values);form.reset();for(const key of Object.keys(values))delete values[key];await render();toast(connecting?'API imeunganishwa. Salio: '+result.balance+' SMS. Kamilisha webhook.':'Webhook imehifadhiwa. Tuma jaribio la webhook kutoka eHub kuhakiki.');return;
  }
  if(form.id==='sms-form'){const draft=await api('market-admin-sms-preview',values);if(!draft.configured)throw Error('eHub bado haijaunganishwa.');if(!smsAttempt||smsAttempt.fingerprint!==draft.fingerprint)smsAttempt={fingerprint:draft.fingerprint,requestId:crypto.randomUUID()};modalForm('Hakiki SMS',`<p><strong>${draft.recipients.length} wapokeaji</strong> · Herufi ${draft.message.length}</p><p class="description sms-preview">${h(draft.message)}</p><p class="small muted">Ukituma, gharama itakatwa kwenye akaunti yako ya eHub. Gharama halisi itaonekana kwenye historia.</p>`,'market-admin-sms-send',{...draft,requestId:smsAttempt.requestId,confirmed:true},'Tuma SMS');return;}
  if(form.id==='search-form')return navigate('/books?q='+encodeURIComponent(values.q));
  if(form.id==='auth-form'){
   const mode=form.dataset.mode;if(mode==='forgot'){await recover(values.email);form.innerHTML='<div class="notice success">Angalia email yako kwa kiungo cha kubadili nenosiri. Ikiwa email haijafika, angalia Spam.</div>'+link('/login','Rudi kuingia','btn secondary');return;}
   if(mode==='reset'){await changePassword(values.password);await signout();me=null;toast('Nenosiri limehifadhiwa. Ingia tena.');return navigate('/login');}
   if(mode==='register'){const logged=await register(values.email,values.password,values.name);if(!logged){form.innerHTML='<div class="notice success">Angalia email yako kuthibitisha akaunti, kisha ingia hapa. Ikiwa email haijafika, angalia Spam.</div>'+link('/login','Fungua ukurasa wa kuingia','btn');return;}}
   else await login(values.email,values.password);
   me=null;await getMe();return navigate(safeNext(new URLSearchParams(location.search).get('next')||(me.role==='admin'?'/admin':'/reader-dashboard')));
  }
  if(form.id==='book-form'){if(form.dataset.id)values.id=form.dataset.id;const result=await api('market-save-book',values);invalidate();toast('Kitabu kimehifadhiwa.');return navigate((location.pathname.startsWith('/admin')?'/admin/books/':'/author/books/')+result.book.id+'/edit',true);}
  if(form.id==='modal-form'){
   const result=await api(form.dataset.api,{...JSON.parse(form.dataset.values),...values});
   if(form.dataset.api==='market-admin-invite'){invalidate();const url=location.origin+'/invite?token='+result.token;modal('Mwaliko uko tayari',`<p class="muted small">${result.email_sent?(result.email_type==='auth_link'?'Kiungo cha kuingia kimetumwa kwa '+h(result.email)+'. Mwaliko utaonekana ndani ya akaunti yake.':'Mwaliko umetumwa kwa '+h(result.email)+'.'):result.email_configured?'Kutumwa kwa email hakujathibitishwa. Mshirikishe '+h(result.email)+' kiungo hiki.':'Email haijaunganishwa. Mshirikishe '+h(result.email)+' kiungo hiki.'} Mwaliko unatumika mara moja ndani ya siku saba.</p><label class="field">Kiungo cha mwaliko<input value="${h(url)}" readonly id="invite-link"></label><p class="small muted">Chagua kiungo, kisha nakili ili kumtumia mwandishi.</p>`);$('#invite-link').select();return;}
   invalidate();$('#modal').close();await render();toast('Taarifa zimehifadhiwa.');return;
  }
  if(form.id==='site-form'){await api('market-admin-settings',values);invalidate();toast('Mipangilio imehifadhiwa.');return render();}
  if(form.id==='profile-form'){await api('market-profile',values);me=null;await getMe();toast('Taarifa zako zimehifadhiwa.');return render();}
  if(form.id==='support-form'){await api('market-support',values);toast('Ombi limepokelewa.');return render();}
  if(form.id==='checkout-form'){
   const verification=form.dataset.verification==='true',fingerprint=JSON.stringify([form.dataset.id,me.id,values.name.trim(),values.phone.replace(/[^0-9]/g,''),verification]);
   let attempt;try{attempt=JSON.parse(sessionStorage.getItem('akili-checkout')||'null');}catch{}
   if(!attempt||attempt.fingerprint!==fingerprint||Date.now()-attempt.createdAt>4*3600000){const bytes=crypto.getRandomValues(new Uint8Array(32));attempt={fingerprint,bookId:form.dataset.id,userId:me.id,verification,checkoutId:crypto.randomUUID(),clientSecret:Array.from(bytes,x=>x.toString(16).padStart(2,'0')).join(''),createdAt:Date.now()};sessionStorage.setItem('akili-checkout',JSON.stringify(attempt));}
   const result=await api('checkout',{...values,email:me.email,bookId:attempt.bookId,checkoutId:attempt.checkoutId,clientSecret:attempt.clientSecret,verification:attempt.verification});attempt.orderId=result.orderId;attempt.phone=values.phone;attempt.amount=result.amount_tzs;sessionStorage.setItem('akili-checkout',JSON.stringify(attempt));resumePayment(attempt.bookId);return;
  }
 }catch(ex){if(err){err.textContent=ex.message;err.hidden=false;}else toast(ex.message,true);}finally{if(button?.isConnected)button.disabled=false;}
});
function paymentStep(step){document.querySelectorAll('.checkout-steps li').forEach((el,i)=>{el.classList.toggle('done',i<step-1);if(i===step-1)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});}
function resumePayment(bookId){
 let p;try{p=JSON.parse(sessionStorage.getItem('akili-checkout')||'null');}catch{}
 if(!p?.orderId||p.bookId!==bookId||(p.userId&&p.userId!==me.id)||!$('#payment-stage'))return;
 $('#checkout-form').hidden=true;$('#payment-stage').hidden=false;paymentStep(2);
 $('#payment-detail').textContent=(p.amount?money(p.amount)+' · ':'')+'Oda '+p.orderId.slice(0,8)+(p.phone?' · Simu …'+p.phone.slice(-4):'');
 clearInterval(paymentTimer);paymentTimer=setInterval(checkPayment,6000);checkPayment();
}
let checking=false;
async function checkPayment(){
 if(checking)return;let p;try{p=JSON.parse(sessionStorage.getItem('akili-checkout')||'null');}catch{}if(!p?.orderId)return;
 checking=true;const button=document.querySelector('[data-action="check-payment"]');if(button)button.disabled=true;
 try{
  const r=await api('status',{orderId:p.orderId,clientSecret:p.clientSecret});let current;try{current=JSON.parse(sessionStorage.getItem('akili-checkout')||'null');}catch{}if(current?.orderId!==p.orderId)return;
  if(r.status==='paid'){clearInterval(paymentTimer);sessionStorage.removeItem('akili-checkout');invalidate();toast('Malipo yamethibitishwa. Kitabu kipo kwenye maktaba yako.');if(location.pathname==='/checkout/'+p.bookId)return navigate('/my-library');return;}
  if(['failed','expired'].includes(r.status)){
   clearInterval(paymentTimer);sessionStorage.removeItem('akili-checkout');paymentStep(1);
   const form=$('#checkout-form');if(form){form.hidden=false;const error=form.querySelector('#form-error');error.textContent=r.status==='expired'?'Muda wa malipo umeisha. Unaweza kujaribu tena.':'Malipo hayajakamilika. Hakiki namba yako kisha jaribu tena.';error.hidden=false;}
   if($('#payment-stage'))$('#payment-stage').hidden=true;
  }else if($('#payment-message'))$('#payment-message').textContent='Thibitisha ombi kwenye simu yako. Tunasubiri majibu ya malipo.';
 }catch{if($('#payment-message'))$('#payment-message').textContent='Hali ya malipo haijapatikana bado. Subiri au kagua tena; oda yako imehifadhiwa.';}
 finally{checking=false;if(button?.isConnected)button.disabled=false;}
}

(async()=>{const settings=await authSettings();googleEnabled=!!settings.external?.google;await render();})();
